import { create } from "zustand";
import { MigrationService } from "@/services/MigrationService";
import {
  GrantWidenResult,
  MigrationConflictDB,
  MigrationConflictResolveRequest,
  MigrationReportDB,
} from "@/types/migration";

interface MigrationReviewState {
  reports: MigrationReportDB[];
  conflicts: MigrationConflictDB[];
  loading: boolean;
  loaded: boolean;
  load: () => Promise<void>;
  acknowledgeReport: (reportId: string) => Promise<void>;
  widenGrant: (
    reportId: string,
    sectionId: string,
    userId: string,
  ) => Promise<GrantWidenResult>;
  resolveConflict: (
    conflictId: string,
    payload: MigrationConflictResolveRequest,
  ) => Promise<void>;
}

export const useMigrationReviewStore = create<MigrationReviewState>(
  (set, get) => ({
    reports: [],
    conflicts: [],
    loading: false,
    loaded: false,

    load: async () => {
      set({ loading: true });
      try {
        const [reports, conflicts] = await Promise.all([
          MigrationService.listReports(),
          MigrationService.listConflicts(),
        ]);
        set({ reports, conflicts, loaded: true });
      } finally {
        set({ loading: false });
      }
    },

    acknowledgeReport: async (reportId) => {
      const updated = await MigrationService.acknowledgeReport(reportId);
      set({
        reports: get().reports.map((r) => (r.id === reportId ? updated : r)),
      });
    },

    widenGrant: async (reportId, sectionId, userId) => {
      const result = await MigrationService.widenGrant(
        reportId,
        sectionId,
        userId,
      );
      // The report's own grant_changes rows are immutable history — reload
      // it so a second widen attempt on the same pair 404s instead of
      // re-offering an action that no longer applies.
      await get().load();
      return result;
    },

    resolveConflict: async (conflictId, payload) => {
      const updated = await MigrationService.resolveConflict(
        conflictId,
        payload,
      );
      set({
        conflicts: get().conflicts.map((c) =>
          c.id === conflictId ? updated : c,
        ),
      });
    },
  }),
);

/** Reactive selector for a tab/nav badge: reports awaiting acknowledgement
 *  plus conflicts still pending review. */
export const usePendingMigrationReviewCount = (): number =>
  useMigrationReviewStore(
    (s) =>
      s.reports.filter((r) => r.status !== "acknowledged").length +
      s.conflicts.filter((c) => c.status === "pending").length,
  );

import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { ClipboardCheck, FolderTree } from "lucide-react";
import { ViewLayout } from "@/components/layout/ViewLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { formatDate } from "@/utils/dateUtils";
import {
  useMigrationReviewStore,
  usePendingMigrationReviewCount,
} from "@/hooks/useMigrationReviewStore";
import { MigrationReportDB } from "@/types/migration";
import { GrantWidenDialog } from "@/components/view/migration-review-view/GrantWidenDialog";
import { MigrationConflictCard } from "@/components/view/migration-review-view/MigrationConflictCard";

function WorkspaceMappingRow({
  mapping,
}: {
  mapping: Record<string, unknown>;
}) {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view",
  });
  const sourceName = String(
    mapping.source_workspace_name ?? mapping.source_workspace_id,
  );
  const isSurvivor = Boolean(mapping.is_survivor);
  const sectionId = mapping.target_section_id as string | null | undefined;

  return (
    <li className="text-sm flex items-center justify-between gap-2 py-1">
      <span className="truncate">{sourceName}</span>
      <span className="text-muted-foreground text-xs shrink-0">
        {isSurvivor
          ? t("report.mapping-became-workspace")
          : t("report.mapping-became-section", { sectionId })}
      </span>
    </li>
  );
}

function GrantChangeRow({
  reportId,
  change,
}: {
  reportId: string;
  change: Record<string, unknown>;
}) {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view",
  });
  const [dialogOpen, setDialogOpen] = useState(false);
  const userId = change.user_id as string | undefined;
  const sectionId = change.section_id as string | undefined;
  const role = change.role as string | undefined;

  if (!userId || !sectionId) {
    // A public-link change: informational only, nothing to widen.
    return (
      <li className="text-sm text-muted-foreground py-1">
        {t("report.public-link-scoped", { sectionId: change.section_id })}
      </li>
    );
  }

  return (
    <li className="flex items-center justify-between gap-2 py-1">
      <span className="text-sm truncate">
        {t("report.grant-scoped", { role, sectionId })}
      </span>
      <Button variant="outline" size="sm" onClick={() => setDialogOpen(true)}>
        {t("report.widen-action")}
      </Button>
      <GrantWidenDialog
        reportId={reportId}
        sectionId={sectionId}
        userId={userId}
        open={dialogOpen}
        onOpenChange={setDialogOpen}
      />
    </li>
  );
}

function MigrationReportCard({ report }: { report: MigrationReportDB }) {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view",
  });
  const acknowledgeReport = useMigrationReviewStore((s) => s.acknowledgeReport);
  const [acking, setAcking] = useState(false);

  const handleAcknowledge = async () => {
    setAcking(true);
    try {
      await acknowledgeReport(report.id);
    } catch {
      toast.error(t("report.acknowledge-error"));
    } finally {
      setAcking(false);
    }
  };

  return (
    <Card>
      <CardHeader className="flex-row items-center justify-between gap-2">
        <CardTitle className="text-base">
          {t("report.created-on", { date: formatDate(report.created_at) })}
        </CardTitle>
        <Badge
          variant={report.status === "acknowledged" ? "secondary" : "default"}
        >
          {t(`report.status-${report.status}`)}
        </Badge>
      </CardHeader>
      <CardContent className="space-y-4">
        {report.workspace_mappings.length > 0 && (
          <div>
            <h3 className="text-sm font-medium mb-1">
              {t("report.workspaces-title")}
            </h3>
            <ul className="divide-y">
              {report.workspace_mappings.map((m, i) => (
                <WorkspaceMappingRow key={i} mapping={m} />
              ))}
            </ul>
          </div>
        )}

        {report.grant_changes.length > 0 && (
          <div>
            <h3 className="text-sm font-medium mb-1">
              {t("report.access-title")}
            </h3>
            <ul className="divide-y">
              {report.grant_changes.map((c, i) => (
                <GrantChangeRow key={i} reportId={report.id} change={c} />
              ))}
            </ul>
          </div>
        )}

        {report.converted_virtual_views.length > 0 && (
          <div>
            <h3 className="text-sm font-medium mb-1">
              {t("report.converted-views-title")}
            </h3>
            <ul className="list-disc list-inside text-sm space-y-0.5">
              {report.converted_virtual_views.map((v, i) => (
                <li key={i}>{String(v.name ?? v.virtual_view_id)}</li>
              ))}
            </ul>
          </div>
        )}

        {report.dropped_virtual_views.length > 0 && (
          <div>
            <h3 className="text-sm font-medium mb-1">
              {t("report.dropped-views-title")}
            </h3>
            <ul className="list-disc list-inside text-sm space-y-0.5 text-muted-foreground">
              {report.dropped_virtual_views.map((v, i) => (
                <li key={i}>{String(v.name ?? v.virtual_view_id)}</li>
              ))}
            </ul>
          </div>
        )}

        <div className="flex justify-end">
          <Button
            size="sm"
            disabled={report.status === "acknowledged" || acking}
            onClick={() => void handleAcknowledge()}
          >
            {report.status === "acknowledged"
              ? t("report.acknowledged")
              : t("report.acknowledge")}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

export const MigrationReviewView = () => {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view",
  });
  const reports = useMigrationReviewStore((s) => s.reports);
  const conflicts = useMigrationReviewStore((s) => s.conflicts);
  const loading = useMigrationReviewStore((s) => s.loading);
  const loaded = useMigrationReviewStore((s) => s.loaded);
  const load = useMigrationReviewStore((s) => s.load);
  const pendingCount = usePendingMigrationReviewCount();

  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const pendingConflicts = conflicts.filter((c) => c.status === "pending");
  const decidedConflicts = conflicts.filter((c) => c.status !== "pending");
  const isEmpty = loaded && reports.length === 0 && conflicts.length === 0;

  return (
    <ViewLayout title={t("title")}>
      {!loaded && loading ? (
        <p className="text-sm text-muted-foreground">{t("loading")}</p>
      ) : isEmpty ? (
        <Empty className="flex-1 border">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <ClipboardCheck className="size-6" />
            </EmptyMedia>
            <EmptyTitle>{t("empty-title")}</EmptyTitle>
            <EmptyDescription>{t("empty-description")}</EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <Tabs defaultValue="report" className="flex-1 min-h-0 flex flex-col">
          <TabsList variant="line" className="flex-none">
            <TabsTrigger value="report">
              <FolderTree className="size-4" />
              {t("tab-report")}
            </TabsTrigger>
            <TabsTrigger value="checklist">
              <ClipboardCheck className="size-4" />
              {t("tab-checklist")}
              {pendingCount > 0 && (
                <Badge variant="destructive" className="ml-1">
                  {pendingConflicts.length}
                </Badge>
              )}
            </TabsTrigger>
          </TabsList>
          <TabsContent
            value="report"
            className="flex-1 min-h-0 overflow-auto space-y-4 pt-3"
          >
            {reports.length === 0 ? (
              <p className="text-sm text-muted-foreground">{t("no-reports")}</p>
            ) : (
              reports.map((r) => <MigrationReportCard key={r.id} report={r} />)
            )}
          </TabsContent>
          <TabsContent
            value="checklist"
            className="flex-1 min-h-0 overflow-auto space-y-3 pt-3"
          >
            {pendingConflicts.length === 0 ? (
              <p className="text-sm text-muted-foreground">
                {t("checklist.no-pending")}
              </p>
            ) : (
              pendingConflicts.map((c) => (
                <MigrationConflictCard key={c.id} conflict={c} />
              ))
            )}
            {decidedConflicts.length > 0 && (
              <div className="pt-4">
                <h3 className="text-sm font-medium mb-2 text-muted-foreground">
                  {t("checklist.history-title")}
                </h3>
                <div className="space-y-2">
                  {decidedConflicts.map((c) => (
                    <MigrationConflictCard key={c.id} conflict={c} />
                  ))}
                </div>
              </div>
            )}
          </TabsContent>
        </Tabs>
      )}
    </ViewLayout>
  );
};

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useMigrationReviewStore } from "@/hooks/useMigrationReviewStore";
import { GrantAccessSummary } from "@/types/migration";

interface Props {
  reportId: string;
  sectionId: string;
  userId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function AccessSummaryCard({ summary }: { summary: GrantAccessSummary }) {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view.widen-dialog",
  });
  return (
    <div className="rounded-md border p-3 space-y-1">
      <p className="text-sm font-medium">
        {summary.scope === "workspace"
          ? t("scope-workspace")
          : t("scope-section")}
      </p>
      <p className="text-xs text-muted-foreground capitalize">{summary.role}</p>
      <div className="flex flex-wrap gap-1">
        {summary.restrictions.length === 0 ? (
          <Badge variant="secondary">{t("no-restrictions")}</Badge>
        ) : (
          summary.restrictions.map((r) => (
            <Badge key={r} variant="secondary">
              {r}
            </Badge>
          ))
        )}
      </div>
    </div>
  );
}

export const GrantWidenDialog = ({
  reportId,
  sectionId,
  userId,
  open,
  onOpenChange,
}: Props) => {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view.widen-dialog",
  });
  const widenGrant = useMigrationReviewStore((s) => s.widenGrant);
  const [result, setResult] = useState<{
    before: GrantAccessSummary;
    after: GrantAccessSummary;
  } | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const handleConfirm = async () => {
    setSubmitting(true);
    try {
      const outcome = await widenGrant(reportId, sectionId, userId);
      setResult(outcome);
    } catch {
      toast.error(t("error"));
      onOpenChange(false);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = (next: boolean) => {
    if (!next) setResult(null);
    onOpenChange(next);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("title")}</DialogTitle>
          <DialogDescription>
            {result ? t("done-description") : t("description")}
          </DialogDescription>
        </DialogHeader>
        {result ? (
          <div className="grid grid-cols-2 gap-3">
            <AccessSummaryCard summary={result.before} />
            <AccessSummaryCard summary={result.after} />
          </div>
        ) : null}
        <DialogFooter>
          {result ? (
            <Button onClick={() => handleClose(false)}>{t("close")}</Button>
          ) : (
            <>
              <Button variant="outline" onClick={() => handleClose(false)}>
                {t("cancel")}
              </Button>
              <Button
                onClick={() => void handleConfirm()}
                disabled={submitting}
              >
                {t("confirm")}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatDate } from "@/utils/dateUtils";
import { useMigrationReviewStore } from "@/hooks/useMigrationReviewStore";
import { MergeFieldChoice } from "@/types/merge";
import {
  MigrationConflictAction,
  MigrationConflictDB,
} from "@/types/migration";

// Mirrors app.services.migration.converter._BRIDGE_DRIFT_FIELDS.
const FIELD_LABEL_KEY: Record<string, string> = {
  gender: "field-gender",
  academic_title: "field-academic-title",
  first_name: "field-first-name",
  middle_names: "field-middle-names",
  baptismal_name: "field-baptismal-name",
  last_name: "field-last-name",
  maiden_name: "field-maiden-name",
  date_of_birth: "field-date-of-birth",
  date_of_death: "field-date-of-death",
  deceased: "field-deceased",
  adopted: "field-adopted",
  additional_data: "field-additional-data",
  birthplace: "field-birthplace",
  hometown: "field-hometown",
  cemetery: "field-cemetery",
  places_lived: "field-places-lived",
};

const COMBINABLE_FIELDS = new Set(["additional_data", "places_lived"]);

// A cycle detected while collapsing a bridge pair: nothing to merge
// field-by-field (both rows stayed live), so it's flagged rather than
// listed among the normal field rows — see converter.py's "cycle" outcome.
const CYCLE_SENTINEL = "__cycle__";

interface Props {
  conflict: MigrationConflictDB;
}

export const MigrationConflictCard = ({ conflict }: Props) => {
  const { t } = useTranslation(undefined, {
    keyPrefix: "migration-review-view.checklist",
  });
  const { t: tMerge } = useTranslation(undefined, {
    keyPrefix: "merge-view.resolve",
  });
  const resolveConflict = useMigrationReviewStore((s) => s.resolveConflict);

  const isBridgeMerge = conflict.kind === "bridge_merge";
  const isCycle = conflict.conflicting_fields.includes(CYCLE_SENTINEL);
  const fieldRows = conflict.conflicting_fields.filter(
    (f) => f !== CYCLE_SENTINEL,
  );
  const hasPhotoConflict = conflict.conflicting_media.length > 0;
  const isPending = conflict.status === "pending";

  const [action, setAction] = useState<MigrationConflictAction>(
    isCycle ? "keep_both" : "merge",
  );
  const [fields, setFields] = useState<
    Partial<Record<string, MergeFieldChoice>>
  >({});
  const [submitting, setSubmitting] = useState(false);

  const setFieldChoice = (field: string, choice: MergeFieldChoice) =>
    setFields((prev) => ({ ...prev, [field]: choice }));

  const handleSubmit = async () => {
    setSubmitting(true);
    try {
      await resolveConflict(conflict.id, {
        action,
        fields: action === "merge" ? fields : {},
      });
    } catch {
      toast.error(t("resolve-error"));
    } finally {
      setSubmitting(false);
    }
  };

  const statusVariant =
    conflict.status === "resolved"
      ? "default"
      : conflict.status === "dismissed"
        ? "secondary"
        : "outline";

  return (
    <Card className="p-4 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5">
          <Badge variant="outline">
            {isBridgeMerge
              ? t("kind-bridge-merge")
              : t("kind-virtual-view-match")}
          </Badge>
          {isPending && conflict.blocks_finalization && (
            <Badge variant="destructive">{t("blocks-finalization")}</Badge>
          )}
        </div>
        <Badge variant={statusVariant}>{t(`status-${conflict.status}`)}</Badge>
      </div>

      {isPending ? (
        <>
          {isCycle && (
            <p className="text-sm text-muted-foreground bg-muted/30 rounded-sm px-3 py-2">
              {t("cycle-notice")}
            </p>
          )}

          {isBridgeMerge && (fieldRows.length > 0 || hasPhotoConflict) && (
            <div className="space-y-1.5">
              {fieldRows.map((field) => {
                const values = conflict.field_values[field] ?? {};
                const valueA = String(values[conflict.member_a_id] ?? "—");
                const valueB = String(values[conflict.member_b_id] ?? "—");
                const combinable = COMBINABLE_FIELDS.has(field);
                return (
                  <div
                    key={field}
                    className="grid grid-cols-[1fr_1fr_auto] gap-2 items-center rounded-sm bg-muted/30 px-3 py-2"
                  >
                    <div className="min-w-0">
                      <p className="text-xs text-muted-foreground">
                        {t(FIELD_LABEL_KEY[field] ?? "field-unknown")}
                      </p>
                      <p className="text-sm break-words">{valueA}</p>
                    </div>
                    <div className="min-w-0">
                      <p className="text-xs text-muted-foreground">&nbsp;</p>
                      <p className="text-sm break-words">{valueB}</p>
                    </div>
                    <div className="w-28">
                      {action === "merge" ? (
                        <Select
                          value={fields[field] ?? "a"}
                          onValueChange={(v) =>
                            setFieldChoice(field, v as MergeFieldChoice)
                          }
                        >
                          <SelectTrigger className="h-7 text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="a">
                              {tMerge("field-choice-a")}
                            </SelectItem>
                            <SelectItem value="b">
                              {tMerge("field-choice-b")}
                            </SelectItem>
                            {combinable && (
                              <SelectItem value="combine">
                                {tMerge("field-choice-combine")}
                              </SelectItem>
                            )}
                          </SelectContent>
                        </Select>
                      ) : null}
                    </div>
                  </div>
                );
              })}
              {hasPhotoConflict && (
                <div className="grid grid-cols-[1fr_1fr_auto] gap-2 items-center rounded-sm bg-muted/30 px-3 py-2">
                  <p className="text-sm col-span-2">{t("field-photo")}</p>
                  <div className="w-28">
                    {action === "merge" ? (
                      <Select
                        value={fields.image_data ?? "a"}
                        onValueChange={(v) =>
                          setFieldChoice("image_data", v as MergeFieldChoice)
                        }
                      >
                        <SelectTrigger className="h-7 text-xs">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="a">
                            {tMerge("field-choice-a")}
                          </SelectItem>
                          <SelectItem value="b">
                            {tMerge("field-choice-b")}
                          </SelectItem>
                        </SelectContent>
                      </Select>
                    ) : null}
                  </div>
                </div>
              )}
            </div>
          )}

          <div className="flex items-center justify-between gap-3 pt-1">
            <div className="flex items-center gap-2">
              <Label className="text-xs text-muted-foreground">
                {tMerge("action-label")}
              </Label>
              <Select
                value={action}
                onValueChange={(v) => setAction(v as MigrationConflictAction)}
              >
                <SelectTrigger className="h-8 w-36 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {!isCycle && (
                    <SelectItem value="merge">
                      {tMerge("action-merge")}
                    </SelectItem>
                  )}
                  <SelectItem value="keep_both">
                    {tMerge("action-keep-both")}
                  </SelectItem>
                  <SelectItem value="dismiss">{t("action-dismiss")}</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <Button
              size="sm"
              onClick={() => void handleSubmit()}
              disabled={submitting}
            >
              {t("resolve")}
            </Button>
          </div>
        </>
      ) : (
        <p className="text-xs text-muted-foreground">
          {conflict.resolved_at &&
            t("resolved-on", { date: formatDate(conflict.resolved_at) })}
        </p>
      )}
    </Card>
  );
};

diff --git a/frontend/scripts/check-i18n.mjs b/frontend/scripts/check-i18n.mjs
index 7ceb30a..e4a41d1 100644
--- a/frontend/scripts/check-i18n.mjs
+++ b/frontend/scripts/check-i18n.mjs
@@ -1,99 +1,105 @@
 import { promises as fs } from "fs";
 import path from "path";
 import { glob } from "glob";

 const SRC_DIR = "src";
 const LOCALES_DIR = "src/i18n/locales";

 // Keys assembled at runtime via template literals or variable lookup cannot be
 // detected by static analysis. List their key prefixes here so the checker does
 // not report them as unused. Keep this list in sync with the code that builds
 // the keys dynamically.
 //
 // Format: each entry is a string prefix. Any key whose full dot-path starts
 // with one of these prefixes is considered intentionally dynamic.
 const DYNAMIC_KEY_PREFIXES = [
   // t(ISSUE_TYPE_KEY[issue.issue_type] ?? "issue-unknown")  — QualityReportView
   "quality-report-view.issue-",
   // t(`severity-${issue.severity}`)  — QualityReportView / IssueCard
   "quality-report-view.severity-",
